const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

// Read all registers in parallel
const reads = [
    { name: 'reg278', address: 278, quantity: 1 },
    { name: 'reg279', address: 279, quantity: 1 },
    { name: 'arcFaultMode', address: 281, quantity: 1 },
    { name: 'islandProtection', address: 183, quantity: 1 },
    { name: 'ctRatio', address: 447, quantity: 1 },
    { name: 'meterCtRatio', address: 448, quantity: 1 },
    { name: 'parallelConfig', address: 436, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name
}));

return [messages];

const flowKey = 'iaf_reads';
let collected = flow.get(flowKey) || {};
let expectedCount = 7;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

collected[msg.readName] = data[0];

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const reg278 = data.reg278;
const reg279 = data.reg279;
const reg436 = data.parallelConfig;

// Parse 278 bit fields (10=disable, 11=enable)
const genPeakShavingBits = (reg278 >> 2) & 0x03;
const gridPeakShavingBits = (reg278 >> 4) & 0x03;
const smartLoadOnGridBits = (reg278 >> 6) & 0x03;
const externalRelayBits = (reg278 >> 8) & 0x03;
const lithiumBatteryLossBits = (reg278 >> 10) & 0x03;

// Parse arc fault mode
const arcFaultMode = data.arcFaultMode;

// Parse parallel config (436)
const parallelEnabled = (reg436 & 0x01) === 1;
const parallelRoleBit = (reg436 >> 1) & 0x01;
const parallelPhaseBits = (reg436 >> 8) & 0x03;
const modbusAddress = (reg436 >> 10) & 0x3F;

let parallelRole = "standalone";
if (parallelEnabled) {
    parallelRole = parallelRoleBit === 1 ? "master" : "slave";
}

let parallelPhase = "A";
switch(parallelPhaseBits) {
    case 0: parallelPhase = "A"; break;
    case 1: parallelPhase = "B"; break;
    case 2: parallelPhase = "C"; break;
    case 3: parallelPhase = "void"; break;
}

const state = {
    kind: "InverterAdvancedFunctionConfigState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    gatewayId: gatewayId,

    advancedFunctionWord1Raw: reg278,
    advancedFunctionWord2Raw: reg279,

    arcFault: {
        mode: arcFaultMode,
        enabled: arcFaultMode === 0x01
    },

    systemSelfCheckEnabled: null,

    generatorPeakShavingEnabled: genPeakShavingBits === 0x03,
    gridPeakShavingEnabled: gridPeakShavingBits === 0x03,

    smartLoadOnGridAlwaysOn: smartLoadOnGridBits === 0x03,
    externalRelayEnabled: externalRelayBits === 0x03,

    islandProtectionEnabled: data.islandProtection === 1,

    externalMeter: {
        ctRatio: data.ctRatio,
        meterCtRatio: data.meterCtRatio,
        phase: null
    },

    lithiumBatteryLossFaultEnabled: lithiumBatteryLossBits === 0x03,

    drmEnabled: null,

    parallel: {
        enabled: parallelEnabled,
        role: parallelRole,
        phase: parallelPhase,
        modbusAddress: modbusAddress
    }
};

msg.payload = state;
msg.state = state;

node.status({ fill: "green", shape: "dot", text: `Parallel: ${parallelRole}` });

return msg;

const params = msg.rpcParams || {};
const writes = [];

// For bit field writes to 278, we need to read current value first
let needs278Read = false;

if (params.generatorPeakShavingEnabled !== undefined ||
    params.gridPeakShavingEnabled !== undefined ||
    params.smartLoadOnGridAlwaysOn !== undefined ||
    params.externalRelayEnabled !== undefined ||
    params.lithiumBatteryLossFaultEnabled !== undefined) {
    needs278Read = true;
    writes.push({
        name: 'reg278_bitfields',
        address: 278,
        isBitField: true,
        params: {
            generatorPeakShavingEnabled: params.generatorPeakShavingEnabled,
            gridPeakShavingEnabled: params.gridPeakShavingEnabled,
            smartLoadOnGridAlwaysOn: params.smartLoadOnGridAlwaysOn,
            externalRelayEnabled: params.externalRelayEnabled,
            lithiumBatteryLossFaultEnabled: params.lithiumBatteryLossFaultEnabled
        }
    });
}

// Arc fault mode (281)
if (params.arcFault && params.arcFault.mode !== undefined) {
    writes.push({
        name: 'arcFaultMode',
        address: 281,
        value: [params.arcFault.mode]
    });
}

// Island protection (183)
if (params.islandProtectionEnabled !== undefined) {
    writes.push({
        name: 'islandProtection',
        address: 183,
        value: [params.islandProtectionEnabled ? 1 : 0]
    });
}

// CT ratios
if (params.externalMeter) {
    if (params.externalMeter.ctRatio !== undefined) {
        writes.push({
            name: 'ctRatio',
            address: 447,
            value: [params.externalMeter.ctRatio]
        });
    }
    if (params.externalMeter.meterCtRatio !== undefined) {
        writes.push({
            name: 'meterCtRatio',
            address: 448,
            value: [params.externalMeter.meterCtRatio]
        });
    }
}

// Parallel config (436) - bit fields
if (params.parallel) {
    const p = params.parallel;
    if (p.enabled !== undefined || p.role !== undefined || 
        p.phase !== undefined || p.modbusAddress !== undefined) {

        let val = 0;

        // Bit 0: enabled
        if (p.enabled) val |= 0x01;

        // Bit 1: role (0=slave, 1=master)
        if (p.enabled && p.role === "master") val |= 0x02;

        // Bits 8-9: phase
        let phaseBits = 0;
        if (p.phase === "A") phaseBits = 0;
        else if (p.phase === "B") phaseBits = 1;
        else if (p.phase === "C") phaseBits = 2;
        else if (p.phase === "void") phaseBits = 3;
        val |= (phaseBits << 8);

        // Bits 10-15: modbus address (0-63)
        if (p.modbusAddress !== undefined) {
            val |= ((p.modbusAddress & 0x3F) << 10);
        }

        writes.push({
            name: 'parallelConfig',
            address: 436,
            value: [val]
        });
    }
}

if (writes.length === 0) {
    node.status({ fill: "red", shape: "dot", text: "No valid params" });
    node.error("No valid parameters to write");
    return null;
}

global.set('iaf_write_queue', writes);
global.set('iaf_write_index', 0);
global.set('iaf_needs_278_read', needs278Read);
flow.set('iaf_original_msg', msg);

node.status({ fill: "yellow", shape: "dot", text: `Queued ${writes.length} writes` });

return msg;

const queue = global.get('iaf_write_queue') || [];
let index = global.get('iaf_write_index') || 0;

if (index >= queue.length) {
    node.status({ fill: "green", shape: "dot", text: "All writes complete" });
    global.set('iaf_write_queue', null);
    global.set('iaf_write_index', null);
    global.set('iaf_needs_278_read', null);
    global.set('iaf_reg278_current', null);

    // Trigger auto-read after all writes
    const originalMsg = flow.get('iaf_original_msg');
    if (originalMsg) {
        const readMsg = { operationType: 'read' };
        setTimeout(() => {
            node.send([null, readMsg]);
        }, 500);
    }
    return null;
}

const write = queue[index];

// If this is a bit field write for 278, handle specially
if (write.isBitField && write.address === 278) {
    const reg278Current = global.get('iaf_reg278_current');

    if (reg278Current === null || reg278Current === undefined) {
        // Need to read 278 first
        msg.payload = {
            fc: 3,
            unitid: 1,
            address: 278,
            quantity: 1
        };
        msg.writeInfo = write;
        node.status({ fill: "blue", shape: "dot", text: "Reading reg 278 first" });
        return [msg, null];
    }

    // We have current value, do bit manipulation
    let newVal = reg278Current;
    const p = write.params;

    // Bits 2-3: generatorPeakShavingEnabled
    if (p.generatorPeakShavingEnabled !== undefined) {
        newVal = newVal & ~0x0C; // Clear bits 2-3
        newVal |= p.generatorPeakShavingEnabled ? 0x0C : 0x08; // 11 or 10
    }

    // Bits 4-5: gridPeakShavingEnabled
    if (p.gridPeakShavingEnabled !== undefined) {
        newVal = newVal & ~0x30; // Clear bits 4-5
        newVal |= p.gridPeakShavingEnabled ? 0x30 : 0x20; // 11 or 10
    }

    // Bits 6-7: smartLoadOnGridAlwaysOn
    if (p.smartLoadOnGridAlwaysOn !== undefined) {
        newVal = newVal & ~0xC0; // Clear bits 6-7
        newVal |= p.smartLoadOnGridAlwaysOn ? 0xC0 : 0x80; // 11 or 10
    }

    // Bits 8-9: externalRelayEnabled
    if (p.externalRelayEnabled !== undefined) {
        newVal = newVal & ~0x0300; // Clear bits 8-9
        newVal |= p.externalRelayEnabled ? 0x0300 : 0x0200; // 11 or 10
    }

    // Bits 10-11: lithiumBatteryLossFaultEnabled
    if (p.lithiumBatteryLossFaultEnabled !== undefined) {
        newVal = newVal & ~0x0C00; // Clear bits 10-11
        newVal |= p.lithiumBatteryLossFaultEnabled ? 0x0C00 : 0x0800; // 11 or 10
    }

    msg.payload = {
        fc: 16,
        unitid: 1,
        address: 278,
        quantity: 1,
        value: [newVal]
    };
    msg.writeInfo = write;
    node.status({ fill: "yellow", shape: "dot", text: `Writing reg 278 (${index + 1}/${queue.length})` });
    global.set('iaf_write_index', index + 1);
    return [null, msg];
}

// Regular write
msg.payload = {
    fc: 16,
    unitid: 1,
    address: write.address,
    quantity: write.value.length,
    value: write.value
};

msg.writeInfo = write;

node.status({ fill: "yellow", shape: "dot", text: `Writing ${write.name} (${index + 1}/${queue.length})` });

// Increment index for next write
global.set('iaf_write_index', index + 1);

return [null, msg];

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

const reg278 = Array.isArray(data) ? data[0] : 0;
global.set('iaf_reg278_current', reg278);

node.status({ fill: "blue", shape: "dot", text: "Reg 278 read: " + reg278 });

// Retry the write executor
return msg;

// Filter out confirmation messages
const isConfirmation = msg.payload && 
                       msg.payload.address !== undefined && 
                       msg.payload.length !== undefined &&
                       !msg.payload.error;

if (isConfirmation) {
    // Continue to next write after delay
    setTimeout(() => {
        node.send(msg);
    }, 500);
    return null;
}

// Error case - still continue
node.warn("Write error, continuing: " + JSON.stringify(msg.payload));
setTimeout(() => {
    node.send(msg);
}, 500);
return null;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;
